from app import create_app

client = create_app().test_client()


def post(items, priority=False):
    return client.post("/orders", json={"items": items, "priority": priority})


def test_standard():
    r = post(3)
    assert r.status_code == 200
    assert r.get_json() == {"items": 3, "tier": "standard", "fee": 10}


def test_bulk_boundary():
    body = post(10).get_json()
    assert body["tier"] == "bulk" and body["fee"] == 5


def test_priority_is_express():
    body = post(2, priority=True).get_json()
    assert body["tier"] == "express" and body["fee"] == 20


def test_priority_beats_bulk():
    assert post(50, priority=True).get_json()["tier"] == "express"

